{
  "name": "Polyglot i+1: Natural Method Language Studio",
  "description": "An advanced language learning application based on the Natural Method (i+1), using Gemini AI to generate customized content for your specific vocabulary level.",
  "requestFramePermissions": [
    "microphone"
  ]
}

export type CEFRLevel = 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2';

export interface Sentence {
  id: number;
  original: string;
  translation: string;
  new_element: string;
  explanation: string;
}

export interface StoryResponse {
  story_title: string;
  level_target: CEFRLevel;
  sentences: Sentence[];
  estimated_vocab_count: string;
  new_words_to_add: string[];
}

export interface UserProfile {
  name: string;
  targetLanguage: string;
  nativeLanguage: string;
  level: CEFRLevel;
  knownWords: string[];
}

export interface HistoryItem extends StoryResponse {
  timestamp: number;
  completed: boolean;
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { GoogleGenAI, Type } from "@google/genai";
import { CEFRLevel, StoryResponse } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateStory = async (
  targetLanguage: string,
  nativeLanguage: string,
  level: CEFRLevel,
  knownWords: string[]
): Promise<StoryResponse> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const prompt = `
    Act as a Natural Language Acquisition Specialist and Polyglot. 
    Generate study content following the Natural Method (i+1) strictly.

    Target Language: ${targetLanguage}
    Native Language (for translations): ${nativeLanguage}
    CEFR Level: ${level}
    Known Words List: [${knownWords.slice(0, 500).join(", ")}]

    RULES:
    1. i+1 METHOD: Create a short story or paragraph where almost all words are known based on the provided list, EXCEPT for one new element (word or structure) introduced per sentence or a few per story.
    2. CONTEXT: Ensure the story is coherent, interesting, and uses natural phrasing.
    3. TARGET: Ensure the vocabulary strictly matches the ${level} difficulty.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          story_title: { type: Type.STRING },
          level_target: { type: Type.STRING },
          sentences: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                original: { type: Type.STRING },
                translation: { type: Type.STRING },
                new_element: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "original", "translation", "new_element", "explanation"]
            }
          },
          estimated_vocab_count: { type: Type.STRING },
          new_words_to_add: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["story_title", "level_target", "sentences", "estimated_vocab_count", "new_words_to_add"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useState, useEffect, useCallback } from 'react';
import { UserProfile, HistoryItem, CEFRLevel, StoryResponse } from './types';
import { generateStory } from './services/geminiService';
import Dashboard from './components/Dashboard';
import StudyArea from './components/StudyArea';
import History from './components/History';
import Settings from './components/Settings';
import { BookOpen, LayoutDashboard, History as HistoryIcon, Settings as SettingsIcon, Download, Upload } from 'lucide-react';

const STORAGE_KEY = 'polyglot_i1_data';

const DEFAULT_PROFILE: UserProfile = {
  name: 'User',
  targetLanguage: 'English',
  nativeLanguage: 'Portuguese',
  level: 'A1',
  knownWords: ['hello', 'world', 'the', 'is', 'a', 'to', 'in', 'and']
};

const App: React.FC = () => {
  const [profile, setProfile] = useState<UserProfile>(DEFAULT_PROFILE);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'study' | 'history' | 'settings'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [currentStory, setCurrentStory] = useState<StoryResponse | null>(null);

  // Load initial data
  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const { profile, history } = JSON.parse(savedData);
        if (profile) setProfile(profile);
        if (history) setHistory(history);
      } catch (e) {
        console.error("Failed to parse stored data", e);
      }
    }
  }, []);

  // Persist data
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ profile, history }));
  }, [profile, history]);

  const handleGenerateStory = async () => {
    setLoading(true);
    try {
      const story = await generateStory(
        profile.targetLanguage,
        profile.nativeLanguage,
        profile.level,
        profile.knownWords
      );
      setCurrentStory(story);
      setActiveTab('study');
    } catch (error) {
      alert("Error generating story. Please try again.");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleCompleteLesson = (story: StoryResponse) => {
    const updatedKnownWords = Array.from(new Set([...profile.knownWords, ...story.new_words_to_add]));
    setProfile(prev => ({ ...prev, knownWords: updatedKnownWords }));

    const newHistoryItem: HistoryItem = {
      ...story,
      timestamp: Date.now(),
      completed: true
    };

    setHistory(prev => [newHistoryItem, ...prev]);
    setCurrentStory(null);
    setActiveTab('dashboard');
    alert("Congratulations! Your vocabulary has grown.");
  };

  const handleExport = () => {
    const data = JSON.stringify({ profile, history }, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `polyglot_progress_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.profile) setProfile(data.profile);
        if (data.history) setHistory(data.history);
        alert("Progress imported successfully!");
      } catch (err) {
        alert("Invalid file format.");
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row">
      {/* Sidebar */}
      <nav className="w-full md:w-64 bg-slate-900 text-white p-6 flex flex-col shrink-0">
        <div className="flex items-center gap-2 mb-10">
          <div className="bg-indigo-500 p-2 rounded-lg">
            <BookOpen size={24} />
          </div>
          <h1 className="text-xl font-bold tracking-tight">Polyglot i+1</h1>
        </div>

        <div className="flex flex-col gap-2 flex-grow">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-indigo-600 shadow-lg shadow-indigo-900/50' : 'hover:bg-slate-800'}`}
          >
            <LayoutDashboard size={20} /> Dashboard
          </button>
          <button 
            onClick={() => setActiveTab('study')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-600 shadow-lg shadow-indigo-900/50' : 'hover:bg-slate-800'}`}
          >
            <BookOpen size={20} /> Study Area
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'history' ? 'bg-indigo-600 shadow-lg shadow-indigo-900/50' : 'hover:bg-slate-800'}`}
          >
            <HistoryIcon size={20} /> History
          </button>
          <button 
            onClick={() => setActiveTab('settings')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 shadow-lg shadow-indigo-900/50' : 'hover:bg-slate-800'}`}
          >
            <SettingsIcon size={20} /> Settings
          </button>
        </div>

        <div className="mt-auto pt-6 border-t border-slate-800 flex flex-col gap-2">
          <button onClick={handleExport} className="flex items-center gap-2 text-sm text-slate-400 hover:text-white transition-colors px-4">
            <Download size={16} /> Export Data
          </button>
          <label className="flex items-center gap-2 text-sm text-slate-400 hover:text-white transition-colors px-4 cursor-pointer">
            <Upload size={16} /> Import Data
            <input type="file" className="hidden" onChange={handleImport} accept=".json" />
          </label>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-grow p-4 md:p-10 overflow-y-auto max-h-screen">
        {activeTab === 'dashboard' && (
          <Dashboard 
            profile={profile} 
            onGenerate={handleGenerateStory} 
            loading={loading} 
            historyCount={history.length}
          />
        )}
        {activeTab === 'study' && (
          <StudyArea 
            story={currentStory} 
            loading={loading}
            onGenerate={handleGenerateStory}
            onComplete={handleCompleteLesson}
            targetLanguage={profile.targetLanguage}
          />
        )}
        {activeTab === 'history' && (
          <History history={history} />
        )}
        {activeTab === 'settings' && (
          <Settings profile={profile} setProfile={setProfile} />
        )}
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { UserProfile } from '../types';
import { Award, Zap, BookOpen, ChevronRight, Loader2 } from 'lucide-react';

interface DashboardProps {
  profile: UserProfile;
  onGenerate: () => void;
  loading: boolean;
  historyCount: number;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, onGenerate, loading, historyCount }) => {
  const getProgressWidth = (level: string) => {
    const levels = ['A1', 'A2', 'B1', 'B2', 'C1', 'C2'];
    const idx = levels.indexOf(level);
    return `${((idx + 1) / levels.length) * 100}%`;
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-900">Welcome back, {profile.name}!</h2>
          <p className="text-slate-500">Ready for your next i+1 breakthrough?</p>
        </div>
        <button
          onClick={onGenerate}
          disabled={loading}
          className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-400 text-white font-semibold py-3 px-6 rounded-xl shadow-lg shadow-indigo-200 transition-all flex items-center justify-center gap-2"
        >
          {loading ? (
            <Loader2 className="animate-spin" size={20} />
          ) : (
            <Zap size={20} />
          )}
          Generate New Lesson
        </button>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col gap-4">
          <div className="bg-amber-100 text-amber-700 p-2 rounded-lg w-fit">
            <Award size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-slate-500 uppercase tracking-wider">CEFR Level</p>
            <p className="text-2xl font-bold text-slate-900">{profile.level}</p>
          </div>
          <div className="w-full bg-slate-100 h-2 rounded-full overflow-hidden">
            <div 
              className="bg-amber-500 h-full transition-all duration-1000" 
              style={{ width: getProgressWidth(profile.level) }}
            />
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col gap-4">
          <div className="bg-blue-100 text-blue-700 p-2 rounded-lg w-fit">
            <BookOpen size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-slate-500 uppercase tracking-wider">Estimated Vocabulary</p>
            <p className="text-2xl font-bold text-slate-900">{profile.knownWords.length} words</p>
          </div>
          <p className="text-xs text-slate-400">Based on your known words list</p>
        </div>

        <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 flex flex-col gap-4">
          <div className="bg-emerald-100 text-emerald-700 p-2 rounded-lg w-fit">
            <Zap size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-slate-500 uppercase tracking-wider">Lessons Completed</p>
            <p className="text-2xl font-bold text-slate-900">{historyCount}</p>
          </div>
          <p className="text-xs text-slate-400">Consistent learning pays off</p>
        </div>
      </div>

      <div className="bg-indigo-900 rounded-2xl p-8 text-white relative overflow-hidden">
        <div className="relative z-10 space-y-4 max-w-lg">
          <h3 className="text-2xl font-bold">The i+1 Philosophy</h3>
          <p className="text-indigo-100 leading-relaxed">
            The Natural Method suggests that we acquire language best when we are exposed to input that is just 
            one step beyond our current stage (i+1). Our AI analyzes your known vocabulary to craft sentences 
            that challenge you without overwhelming you.
          </p>
          <div className="pt-2">
            <button 
              onClick={onGenerate}
              className="group flex items-center gap-2 text-indigo-200 hover:text-white transition-colors"
            >
              Start learning now <ChevronRight size={18} className="group-hover:translate-x-1 transition-transform" />
            </button>
          </div>
        </div>
        <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/20 rounded-full -mr-20 -mt-20 blur-3xl"></div>
        <div className="absolute bottom-0 right-0 w-48 h-48 bg-purple-500/20 rounded-full mr-10 -mb-10 blur-3xl"></div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { StoryResponse, Sentence } from '../types';
import { Volume2, ChevronDown, ChevronUp, Download, CheckCircle2, Loader2, Sparkles, Languages } from 'lucide-react';

interface StudyAreaProps {
  story: StoryResponse | null;
  loading: boolean;
  onGenerate: () => void;
  onComplete: (story: StoryResponse) => void;
  targetLanguage: string;
}

const SentenceCard: React.FC<{ sentence: Sentence; targetLanguage: string }> = ({ sentence, targetLanguage }) => {
  const [showTranslation, setShowTranslation] = useState(false);

  const speak = () => {
    const utterance = new SpeechSynthesisUtterance(sentence.original);
    // Rough language mapping
    const langMap: Record<string, string> = {
      'English': 'en-US',
      'Portuguese': 'pt-BR',
      'Spanish': 'es-ES',
      'French': 'fr-FR',
      'German': 'de-DE',
      'Italian': 'it-IT'
    };
    utterance.lang = langMap[targetLanguage] || 'en-US';
    window.speechSynthesis.speak(utterance);
  };

  const downloadText = () => {
    const text = `${sentence.original}\n${sentence.translation}\nExplanation: ${sentence.explanation}`;
    const blob = new Blob([text], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sentence_${sentence.id}.txt`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden transition-all hover:shadow-md">
      <div className="p-6">
        <div className="flex justify-between items-start gap-4 mb-4">
          <h4 className="text-xl md:text-2xl font-medium text-slate-800 leading-relaxed">
            {sentence.original}
          </h4>
          <div className="flex gap-2 shrink-0">
            <button 
              onClick={speak}
              className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-full transition-all"
              title="Listen"
            >
              <Volume2 size={20} />
            </button>
            <button 
              onClick={downloadText}
              className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-full transition-all"
              title="Download text"
            >
              <Download size={20} />
            </button>
          </div>
        </div>

        <div className="flex flex-col gap-3">
          <button 
            onClick={() => setShowTranslation(!showTranslation)}
            className="flex items-center gap-2 text-sm font-semibold text-indigo-600 hover:text-indigo-700 transition-colors w-fit"
          >
            {showTranslation ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            {showTranslation ? "Hide Translation" : "Show Translation"}
          </button>

          {showTranslation && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <p className="text-slate-600 italic mb-4 p-4 bg-slate-50 rounded-xl border-l-4 border-indigo-200">
                {sentence.translation}
              </p>
              <div className="bg-amber-50 p-4 rounded-xl border border-amber-100">
                <p className="text-xs font-bold text-amber-700 uppercase tracking-widest mb-1 flex items-center gap-1">
                  <Sparkles size={12} /> The "+1" Element: {sentence.new_element}
                </p>
                <p className="text-sm text-amber-900 leading-relaxed">
                  {sentence.explanation}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

const StudyArea: React.FC<StudyAreaProps> = ({ story, loading, onGenerate, onComplete, targetLanguage }) => {
  if (loading) {
    return (
      <div className="h-full flex flex-col items-center justify-center space-y-4 animate-in fade-in duration-500">
        <div className="relative">
          <div className="w-16 h-16 border-4 border-indigo-100 rounded-full"></div>
          <div className="w-16 h-16 border-4 border-indigo-600 rounded-full border-t-transparent animate-spin absolute top-0"></div>
        </div>
        <p className="text-slate-500 font-medium animate-pulse">Consulting the linguistic oracle...</p>
      </div>
    );
  }

  if (!story) {
    return (
      <div className="h-full flex flex-col items-center justify-center text-center space-y-6 max-w-md mx-auto animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="bg-indigo-100 p-6 rounded-3xl text-indigo-600">
          <Languages size={48} />
        </div>
        <div>
          <h3 className="text-2xl font-bold text-slate-900">No Active Lesson</h3>
          <p className="text-slate-500 mt-2">
            Click the button below to generate a story perfectly tuned to your level.
          </p>
        </div>
        <button
          onClick={onGenerate}
          className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold py-4 px-10 rounded-2xl shadow-xl shadow-indigo-200 transition-all flex items-center gap-2"
        >
          <Sparkles size={20} /> Generate My Story
        </button>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4 border-b border-slate-200 pb-6">
        <div>
          <div className="flex items-center gap-2 mb-2">
            <span className="bg-indigo-100 text-indigo-700 text-xs font-bold px-2 py-1 rounded uppercase tracking-wider">
              {story.level_target} Level
            </span>
          </div>
          <h2 className="text-3xl font-bold text-slate-900">{story.story_title}</h2>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={onGenerate}
            className="text-sm font-semibold text-slate-500 hover:text-slate-900 transition-colors"
          >
            Regenerate
          </button>
        </div>
      </header>

      <div className="space-y-6">
        {story.sentences.map((sentence) => (
          <SentenceCard 
            key={sentence.id} 
            sentence={sentence} 
            targetLanguage={targetLanguage} 
          />
        ))}
      </div>

      <div className="pt-10 border-t border-slate-200 text-center">
        <div className="bg-indigo-50 p-8 rounded-3xl space-y-6">
          <div className="flex flex-col items-center gap-2">
            <h3 className="text-xl font-bold text-indigo-900">Finished Reading?</h3>
            <p className="text-indigo-700/70 text-sm">
              Marking this lesson as complete will add {story.new_words_to_add.length} new words to your known vocabulary.
            </p>
          </div>

          <div className="flex flex-wrap justify-center gap-2">
            {story.new_words_to_add.map((word, i) => (
              <span key={i} className="bg-white px-3 py-1 rounded-full text-sm font-medium text-indigo-600 border border-indigo-100">
                + {word}
              </span>
            ))}
          </div>

          <button
            onClick={() => onComplete(story)}
            className="bg-indigo-600 hover:bg-indigo-700 text-white font-bold py-4 px-12 rounded-2xl shadow-xl shadow-indigo-200 transition-all flex items-center justify-center gap-3 w-full md:w-auto mx-auto"
          >
            <CheckCircle2 size={24} /> Lesson Completed
          </button>
        </div>
      </div>
    </div>
  );
};

export default StudyArea;

import React from 'react';
import { HistoryItem } from '../types';
import { Clock, Book, ExternalLink } from 'lucide-react';

interface HistoryProps {
  history: HistoryItem[];
}

const History: React.FC<HistoryProps> = ({ history }) => {
  const formatDate = (timestamp: number) => {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(new Date(timestamp));
  };

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <div>
        <h2 className="text-3xl font-bold text-slate-900">Learning History</h2>
        <p className="text-slate-500">Revisit your past breakthroughs</p>
      </div>

      {history.length === 0 ? (
        <div className="bg-white rounded-2xl p-12 text-center border border-slate-100 shadow-sm space-y-4">
          <div className="bg-slate-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto text-slate-300">
            <Clock size={40} />
          </div>
          <p className="text-slate-500 font-medium italic">Your story list is currently empty.</p>
        </div>
      ) : (
        <div className="grid gap-4">
          {history.map((item, idx) => (
            <div key={idx} className="bg-white p-6 rounded-2xl border border-slate-100 shadow-sm flex items-center justify-between group hover:border-indigo-200 transition-all">
              <div className="flex items-start gap-4">
                <div className="bg-indigo-50 text-indigo-600 p-3 rounded-xl">
                  <Book size={20} />
                </div>
                <div>
                  <h4 className="font-bold text-slate-800 text-lg">{item.story_title}</h4>
                  <div className="flex items-center gap-3 mt-1">
                    <span className="text-xs font-bold text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded uppercase">
                      {item.level_target}
                    </span>
                    <span className="text-xs text-slate-400 flex items-center gap-1">
                      <Clock size={12} /> {formatDate(item.timestamp)}
                    </span>
                  </div>
                  <div className="mt-3 flex flex-wrap gap-2">
                    {item.new_words_to_add.slice(0, 3).map((w, i) => (
                      <span key={i} className="text-[10px] bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded-full border border-emerald-100">
                        {w}
                      </span>
                    ))}
                    {item.new_words_to_add.length > 3 && (
                      <span className="text-[10px] text-slate-400">+{item.new_words_to_add.length - 3} more</span>
                    )}
                  </div>
                </div>
              </div>
              <button className="p-2 text-slate-400 group-hover:text-indigo-600 transition-colors">
                <ExternalLink size={20} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

