const App: React.FC = () => {
  const [profile, setProfile] = useState<UserProfile>(DEFAULT_PROFILE);
  const [history, setHistory] = useState<HistoryItem[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'study' | 'history' | 'settings'>('dashboard');
  const [loading, setLoading] = useState(false);
  const [currentStory, setCurrentStory] = useState<StoryResponse | null>(null);

  const t = useMemo(() => translations[profile.uiLanguage || 'en'], [profile.uiLanguage]);

  // Load initial data
  useEffect(() => {
    const savedData = localStorage.getItem(STORAGE_KEY);
    if (savedData) {
      try {
        const { profile: savedProfile, history: savedHistory } = JSON.parse(savedData);
        if (savedProfile) setProfile({ ...DEFAULT_PROFILE, ...savedProfile });
        if (savedHistory) setHistory(savedHistory);
      } catch (e) {
        console.error("Failed to parse stored data", e);
      }
    }
  }, []);

  // Persist data
  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({ profile, history }));
    // Handle theme
    if (profile.darkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [profile, history]);

  // Notifications logic
  useEffect(() => {
    if (!profile.notificationsEnabled) return;

    const checkNotification = () => {
      const now = new Date();
      const currentStr = `${now.getHours().toString().padStart(2, '0')}:${now.getMinutes().toString().padStart(2, '0')}`;

      if (currentStr === profile.notificationTime) {
        if (Notification.permission === 'granted') {
          new Notification(t.notificationTitle, { body: t.notificationBody });
        }
      }
    };

    const interval = setInterval(checkNotification, 60000); // Check every minute
    return () => clearInterval(interval);
  }, [profile.notificationsEnabled, profile.notificationTime, t]);

  const toggleTheme = () => {
    setProfile(prev => ({ ...prev, darkMode: !prev.darkMode }));
  };

  const handleGenerateStory = async () => {
    setLoading(true);
    try {
      const story = await generateStory(
        profile.targetLanguage,
        profile.nativeLanguage,
        profile.level,
        profile.knownWords
      );
      setCurrentStory(story);
      setActiveTab('study');
    } catch (error) {
      alert("Error generating story. Please try again.");
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  const handleCompleteLesson = (story: StoryResponse) => {
    const updatedKnownWords = Array.from(new Set([...profile.knownWords, ...story.new_words_to_add]));
    setProfile(prev => ({ ...prev, knownWords: updatedKnownWords }));

    const newHistoryItem: HistoryItem = {
      ...story,
      timestamp: Date.now(),
      completed: true
    };

    setHistory(prev => [newHistoryItem, ...prev]);
    setCurrentStory(null);
    setActiveTab('dashboard');
    alert(t.congrats);
  };

  const handleExport = () => {
    const data = JSON.stringify({ profile, history }, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `polyglot_progress_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target?.result as string);
        if (data.profile) setProfile(data.profile);
        if (data.history) setHistory(data.history);
        alert(t.importSuccess);
      } catch (err) {
        alert(t.invalidFile);
      }
    };
    reader.readAsText(file);
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-slate-50 dark:bg-slate-950 transition-colors duration-300">
      {/* Sidebar */}
      <nav className="w-full md:w-64 bg-white dark:bg-slate-900 text-slate-900 dark:text-white p-6 flex flex-col shrink-0 border-r border-slate-200 dark:border-slate-800">
        <div className="flex items-center justify-between mb-10">
          <div className="flex items-center gap-2">
            <div className="bg-indigo-500 p-2 rounded-lg">
              <BookOpen size={24} className="text-white" />
            </div>
            <h1 className="text-xl font-bold tracking-tight">Polyglot i+1</h1>
          </div>
          <button 
            onClick={toggleTheme}
            className="p-2 rounded-full hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors"
          >
            {profile.darkMode ? <Sun size={20} /> : <Moon size={20} />}
          </button>
        </div>

        <div className="flex flex-col gap-2 flex-grow">
          <button 
            onClick={() => setActiveTab('dashboard')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <LayoutDashboard size={20} /> {t.dashboard}
          </button>
          <button 
            onClick={() => setActiveTab('study')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'study' ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <BookOpen size={20} /> {t.studyArea}
          </button>
          <button 
            onClick={() => setActiveTab('history')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'history' ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <HistoryIcon size={20} /> {t.history}
          </button>
          <button 
            onClick={() => setActiveTab('settings')}
            className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === 'settings' ? 'bg-indigo-600 text-white shadow-lg' : 'hover:bg-slate-100 dark:hover:bg-slate-800'}`}
          >
            <SettingsIcon size={20} /> {t.settings}
          </button>
        </div>

        <div className="mt-auto pt-6 border-t border-slate-200 dark:border-slate-800 flex flex-col gap-2">
          <button onClick={handleExport} className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-white transition-colors px-4">
            <Download size={16} /> {t.export}
          </button>
          <label className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-white transition-colors px-4 cursor-pointer">
            <Upload size={16} /> {t.import}
            <input type="file" className="hidden" onChange={handleImport} accept=".json" />
          </label>
        </div>
      </nav>

      {/* Main Content */}
      <main className="flex-grow p-4 md:p-10 overflow-y-auto max-h-screen text-slate-900 dark:text-slate-100">
        {activeTab === 'dashboard' && (
          <Dashboard 
            profile={profile} 
            onGenerate={handleGenerateStory} 
            loading={loading} 
            historyCount={history.length}
            t={t}
          />
        )}
        {activeTab === 'study' && (
          <StudyArea 
            story={currentStory} 
            loading={loading}
            onGenerate={handleGenerateStory}
            onComplete={handleCompleteLesson}
            targetLanguage={profile.targetLanguage}
            t={t}
          />
        )}
        {activeTab === 'history' && (
          <History history={history} />
        )}
        {activeTab === 'settings' && (
          <Settings profile={profile} setProfile={setProfile} />
        )}
      </main>
    </div>
  );
};

export default App;

