import React, { useState, useEffect } from 'react';
import { StoryResponse, Sentence } from '../types';
import { Volume2, ChevronDown, ChevronUp, Download, CheckCircle2, Loader2, Sparkles, Languages, Music } from 'lucide-react';

interface StudyAreaProps {
  story: StoryResponse | null;
  loading: boolean;
  onGenerate: () => void;
  onComplete: (story: StoryResponse) => void;
  targetLanguage: string;
  t: any;
}

const langMap: Record<string, string> = {
  'English': 'en-US',
  'Portuguese': 'pt-BR',
  'Spanish': 'es-ES',
  'French': 'fr-FR',
  'German': 'de-DE',
  'Italian': 'it-IT'
};

const SentenceCard: React.FC<{ sentence: Sentence; targetLanguage: string; t_app: any }> = ({ sentence, targetLanguage, t_app }) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);

  const speak = () => {
    // Cancel any ongoing speech
    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(sentence.original);
    utterance.lang = langMap[targetLanguage] || 'en-US';
    utterance.rate = 0.9; // Slightly slower for study clarity

    // Web Speech API sometimes needs voices to be loaded first
    const voices = window.speechSynthesis.getVoices();
    if (voices.length > 0) {
      const preferredVoice = voices.find(v => v.lang === utterance.lang);
      if (preferredVoice) utterance.voice = preferredVoice;
    }

    window.speechSynthesis.speak(utterance);
  };

  const downloadAudio = async () => {
    setIsDownloading(true);
    try {
      // Since window.speechSynthesis doesn't export to Blob easily, 
      // we use a standard TTS proxy for actual audio download
      const langCode = (langMap[targetLanguage] || 'en-US').split('-')[0];
      const ttsUrl = `https://translate.google.com/translate_tts?ie=UTF-8&q=${encodeURIComponent(sentence.original)}&tl=${langCode}&client=tw-ob`;

      const response = await fetch(ttsUrl);
      const blob = await response.blob();
      const url = URL.createObjectURL(blob);

      const a = document.createElement('a');
      a.href = url;
      a.download = `audio_${sentence.id}.mp3`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Audio download failed:", err);
      // Fallback: download as text if audio proxy fails
      const text = `${sentence.original}\n${sentence.translation}`;
      const blob = new Blob([text], { type: 'text/plain' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `sentence_${sentence.id}.txt`;
      a.click();
      URL.revokeObjectURL(url);
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden transition-all hover:shadow-md">
      <div className="p-6">
        <div className="flex justify-between items-start gap-4 mb-4">
          <h4 className="text-xl md:text-2xl font-medium text-slate-800 dark:text-slate-100 leading-relaxed">
            {sentence.original}
          </h4>
          <div className="flex gap-2 shrink-0">
            <button 
              onClick={speak}
              className="p-2 text-slate-400 dark:text-slate-500 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-slate-800 rounded-full transition-all"
              title="Listen"
            >
              <Volume2 size={22} />
            </button>
            <button 
              onClick={downloadAudio}
              disabled={isDownloading}
              className="p-2 text-slate-400 dark:text-slate-500 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-slate-800 rounded-full transition-all disabled:opacity-50"
              title="Download Audio"
            >
              {isDownloading ? <Loader2 className="animate-spin" size={22} /> : <Music size={22} />}
            </button>
          </div>
        </div>

        <div className="flex flex-col gap-3">
          <button 
            onClick={() => setShowTranslation(!showTranslation)}
            className="flex items-center gap-2 text-sm font-semibold text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300 transition-colors w-fit"
          >
            {showTranslation ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            {showTranslation ? "Hide Translation" : "Show Translation"}
          </button>

          {showTranslation && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <p className="text-slate-600 dark:text-slate-300 italic mb-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-xl border-l-4 border-indigo-200 dark:border-indigo-800">
                {sentence.translation}
              </p>
              <div className="bg-amber-50 dark:bg-amber-900/10 p-4 rounded-xl border border-amber-100 dark:border-amber-900/30">
                <p className="text-xs font-bold text-amber-700 dark:text-amber-500 uppercase tracking-widest mb-1 flex items-center gap-1">
                  <Sparkles size={12} /> The "+1" Element: {sentence.new_element}
                </p>
                <p className="text-sm text-amber-900 dark:text-amber-200 leading-relaxed">
                  {sentence.explanation}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

