// Utility to decode base64 to Uint8Array (SDK standard implementation)
function decodeBase64(base64: string): Uint8Array {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }
  return bytes;
}

// Utility to decode PCM to AudioBuffer
async function decodeAudioData(data: Uint8Array, ctx: AudioContext, sampleRate: number): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const buffer = ctx.createBuffer(1, dataInt16.length, sampleRate);
  const channelData = buffer.getChannelData(0);
  for (let i = 0; i < dataInt16.length; i++) {
    channelData[i] = dataInt16[i] / 32768.0;
  }
  return buffer;
}

// Utility to create a WAV file from PCM data for download
function createWavBlob(pcmData: Int16Array, sampleRate: number): Blob {
  const buffer = new ArrayBuffer(44 + pcmData.length * 2);
  const view = new DataView(buffer);

  const writeString = (offset: number, string: string) => {
    for (let i = 0; i < string.length; i++) {
      view.setUint8(offset + i, string.charCodeAt(i));
    }
  };

  writeString(0, 'RIFF');
  view.setUint32(4, 32 + pcmData.length * 2, true);
  writeString(8, 'WAVE');
  writeString(12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeString(36, 'data');
  view.setUint32(40, pcmData.length * 2, true);

  let offset = 44;
  for (let i = 0; i < pcmData.length; i++, offset += 2) {
    view.setInt16(offset, pcmData[i], true);
  }

  return new Blob([buffer], { type: 'audio/wav' });
}

const SentenceCard: React.FC<{ sentence: Sentence; targetLanguage: string; t_app: any }> = ({ sentence, targetLanguage, t_app }) => {
  const [showTranslation, setShowTranslation] = useState(false);
  const [isProcessingAudio, setIsProcessingAudio] = useState(false);

  const getGeminiAudio = async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: sentence.original }] }],
      config: {
        responseModalities: ["AUDIO"],
        speechConfig: {
          voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
        },
      },
    });

    const base64Data = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Data) throw new Error("No audio data returned");
    return base64Data;
  };

  const speak = async () => {
    if (isProcessingAudio) return;
    setIsProcessingAudio(true);
    try {
      const base64Data = await getGeminiAudio();
      const audioBytes = decodeBase64(base64Data);

      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      const buffer = await decodeAudioData(audioBytes, audioCtx, 24000);

      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(audioCtx.destination);
      source.start();
    } catch (err) {
      console.error("Playback failed:", err);
      alert("Failed to play audio. Check your API Key.");
    } finally {
      setIsProcessingAudio(false);
    }
  };

  const downloadAudio = async () => {
    if (isProcessingAudio) return;
    setIsProcessingAudio(true);
    try {
      const base64Data = await getGeminiAudio();
      const audioBytes = decodeBase64(base64Data);
      const pcmData = new Int16Array(audioBytes.buffer);

      const blob = createWavBlob(pcmData, 24000);
      const url = URL.createObjectURL(blob);

      const a = document.createElement('a');
      a.href = url;
      a.download = `sentence_${sentence.id}.wav`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Download failed:", err);
      alert("Failed to download audio.");
    } finally {
      setIsProcessingAudio(false);
    }
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 overflow-hidden transition-all hover:shadow-md">
      <div className="p-6">
        <div className="flex justify-between items-start gap-4 mb-4">
          <h4 className="text-xl md:text-2xl font-medium text-slate-800 dark:text-slate-100 leading-relaxed">
            {sentence.original}
          </h4>
          <div className="flex gap-2 shrink-0">
            <button 
              onClick={speak}
              disabled={isProcessingAudio}
              className="p-2 text-slate-400 dark:text-slate-500 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-slate-800 rounded-full transition-all disabled:opacity-50"
              title="Listen"
            >
              {isProcessingAudio ? <Loader2 className="animate-spin" size={22} /> : <Volume2 size={22} />}
            </button>
            <button 
              onClick={downloadAudio}
              disabled={isProcessingAudio}
              className="p-2 text-slate-400 dark:text-slate-500 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-indigo-50 dark:hover:bg-slate-800 rounded-full transition-all disabled:opacity-50"
              title="Download Audio (WAV)"
            >
              <Music size={22} />
            </button>
          </div>
        </div>

        <div className="flex flex-col gap-3">
          <button 
            onClick={() => setShowTranslation(!showTranslation)}
            className="flex items-center gap-2 text-sm font-semibold text-indigo-600 dark:text-indigo-400 hover:text-indigo-700 dark:hover:text-indigo-300 transition-colors w-fit"
          >
            {showTranslation ? <ChevronUp size={16} /> : <ChevronDown size={16} />}
            {showTranslation ? "Hide Translation" : "Show Translation"}
          </button>

          {showTranslation && (
            <div className="animate-in fade-in slide-in-from-top-2 duration-300">
              <p className="text-slate-600 dark:text-slate-300 italic mb-4 p-4 bg-slate-50 dark:bg-slate-800 rounded-xl border-l-4 border-indigo-200 dark:border-indigo-800">
                {sentence.translation}
              </p>
              <div className="bg-amber-50 dark:bg-amber-900/10 p-4 rounded-xl border border-amber-100 dark:border-amber-900/30">
                <p className="text-xs font-bold text-amber-700 dark:text-amber-500 uppercase tracking-widest mb-1 flex items-center gap-1">
                  <Sparkles size={12} /> The "+1" Element: {sentence.new_element}
                </p>
                <p className="text-sm text-amber-900 dark:text-amber-200 leading-relaxed">
                  {sentence.explanation}
                </p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

