        <div className="mt-auto pt-6 border-t border-slate-200 dark:border-slate-800 flex flex-col gap-2">
          <button onClick={handleExport} className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-white transition-colors px-4">
            <Download size={16} /> {t.export}
          </button>
          <label className="flex items-center gap-2 text-sm text-slate-500 dark:text-slate-400 hover:text-indigo-600 dark:hover:text-white transition-colors px-4 cursor-pointer">
            <Upload size={16} /> {t.import}
            <input type="file" className="hidden" onChange={handleImport} accept=".json" />
          </label>
        </div>
      </nav>

      <main className="flex-grow p-4 md:p-10 overflow-y-auto max-h-screen text-slate-900 dark:text-slate-100">
        {activeTab === 'dashboard' && (
          <Dashboard 
            profile={profile} 
            onGenerate={handleGenerateStory} 
            loading={loading} 
            historyCount={history.length}
            t={t}
          />
        )}
        {activeTab === 'study' && (
          <StudyArea 
            story={currentStory} 
            loading={loading}
            onGenerate={handleGenerateStory}
            onComplete={handleCompleteLesson}
            targetLanguage={profile.targetLanguage}
            t={t}
          />
        )}
        {activeTab === 'history' && (
          <History history={history} onReopen={handleReopenStory} targetLanguage={profile.targetLanguage} />
        )}
        {activeTab === 'settings' && (
          <Settings profile={profile} setProfile={setProfile} />
        )}
      </main>
    </div>
  );
};

