import React from 'react';
import { UserProfile } from '../types';
import { Award, Zap, BookOpen, ChevronRight, Loader2, Info } from 'lucide-react';

interface DashboardProps {
  profile: UserProfile;
  onGenerate: () => void;
  loading: boolean;
  historyCount: number;
  t: any;
}

const Dashboard: React.FC<DashboardProps> = ({ profile, onGenerate, loading, historyCount, t }) => {
  // Thresholds matching App.tsx calculateLevelFromVocab logic
  const thresholds = [
    { level: 'A1', min: 0, max: 500 },
    { level: 'A2', min: 500, max: 1000 },
    { level: 'B1', min: 1000, max: 2500 },
    { level: 'B2', min: 2500, max: 5000 },
    { level: 'C1', min: 5000, max: 10000 },
    { level: 'C2', min: 10000, max: 15000 }, // Soft cap for visualization
  ];

  const calculateGranularProgress = (wordCount: number) => {
    let currentLevelIdx = thresholds.findIndex(t => wordCount <= t.max);
    if (currentLevelIdx === -1) currentLevelIdx = thresholds.length - 1;

    const currentRange = thresholds[currentLevelIdx];
    const wordsInLevel = wordCount - currentRange.min;
    const levelCapacity = currentRange.max - currentRange.min;

    // Percentage within the current level's segment (0 to 1)
    const segmentProgress = Math.min(Math.max(wordsInLevel / levelCapacity, 0), 1);

    // Total progress: (previous segments + current segment progress) / total segments
    const totalProgress = ((currentLevelIdx + segmentProgress) / thresholds.length) * 100;

    return {
      percentage: totalProgress,
      nextLevelWords: currentRange.max - wordCount,
      isMax: wordCount >= 15000
    };
  };

  const progress = calculateGranularProgress(profile.knownWords.length);

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
