import { GoogleGenAI, Type } from "@google/genai";
import { CEFRLevel, StoryResponse } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateStory = async (
  targetLanguage: string,
  nativeLanguage: string,
  level: CEFRLevel,
  knownWords: string[]
): Promise<StoryResponse> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const prompt = `
    Act as a Natural Language Acquisition Specialist and Polyglot. 
    Generate study content following the Natural Method (i+1) strictly.

    Target Language: ${targetLanguage}
    Native Language (for translations): ${nativeLanguage}
    CEFR Level: ${level}
    Known Words List: [${knownWords.slice(0, 500).join(", ")}]

    RULES:
    1. i+1 METHOD: Create a short story where almost all words are known, EXCEPT for one new element (word or structure) introduced per sentence.
    2. CONTEXT: Ensure the story is coherent and natural.
    3. TARGET: Strictly ${level} difficulty.
    4. PHONETICS: Provide the phonetic transcription (IPA) specifically for the 'new_element' contextually.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          story_title: { type: Type.STRING },
          level_target: { type: Type.STRING },
          sentences: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                original: { type: Type.STRING },
                translation: { type: Type.STRING },
                phonetic: { type: Type.STRING, description: "IPA transcription of the new_element within this sentence" },
                new_element: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "original", "translation", "phonetic", "new_element", "explanation"]
            }
          },
          estimated_vocab_count: { type: Type.STRING },
          new_words_to_add: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["story_title", "level_target", "sentences", "estimated_vocab_count", "new_words_to_add"]
      }
    }
  });

  return JSON.parse(response.text);
};

import React, { useMemo } from 'react';
import { UserProfile, HistoryItem } from '../types';
import { Award, Zap, BookOpen, ChevronRight, Loader2, Info, TrendingUp } from 'lucide-react';

interface DashboardProps {
  profile: UserProfile;
  onGenerate: () => void;
  loading: boolean;
  historyCount: number;
  t: any;
  history: HistoryItem[];
}

const Dashboard: React.FC<DashboardProps> = ({ profile, onGenerate, loading, historyCount, t, history }) => {
  const thresholds = [
    { level: 'A1', min: 0, max: 500 },
    { level: 'A2', min: 500, max: 1000 },
    { level: 'B1', min: 1000, max: 2500 },
    { level: 'B2', min: 2500, max: 5000 },
    { level: 'C1', min: 5000, max: 10000 },
    { level: 'C2', min: 10000, max: 15000 },
  ];

  const calculateLevelProgress = (wordCount: number) => {
    const currentRange = thresholds.find(range => range.level === profile.level) || thresholds[0];
    const wordsInCurrentLevel = wordCount - currentRange.min;
    const levelSize = currentRange.max - currentRange.min;
    const levelPercentage = Math.min(Math.max((wordsInCurrentLevel / levelSize) * 100, 0), 100);

    return {
      percentage: levelPercentage,
      nextLevelWords: currentRange.max - wordCount,
      isMax: profile.level === 'C2' && wordCount >= currentRange.max,
      nextLevel: thresholds[thresholds.indexOf(currentRange) + 1]?.level || 'Mastery'
    };
  };

  const progress = calculateLevelProgress(profile.knownWords.length);

  // Generate growth chart data
  const growthData = useMemo(() => {
    if (history.length === 0) return [];

    // Sort history by timestamp ascending
    const sortedHistory = [...history].sort((a, b) => a.timestamp - b.timestamp);

    let currentCount = profile.knownWords.length;
    // Walk backwards to find history counts
    const points = [];
    points.push({ val: currentCount, label: 'Now' });

    for (let i = sortedHistory.length - 1; i >= 0; i--) {
      currentCount -= sortedHistory[i].new_words_to_add.length;
      points.push({ val: Math.max(0, currentCount), label: new Date(sortedHistory[i].timestamp).toLocaleDateString() });
      if (points.length >= 7) break; // Last 7 milestones
    }

    return points.reverse();
  }, [history, profile.knownWords.length]);

  return (
    <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <header className="flex flex-col md:flex-row md:items-end justify-between gap-4">
        <div>
          <h2 className="text-3xl font-bold text-slate-900 dark:text-white">{t.welcome}, {profile.name}!</h2>
          <p className="text-slate-500 dark:text-slate-400">{t.ready}</p>
        </div>
        <button
          onClick={onGenerate}
          disabled={loading}
          className="bg-indigo-600 hover:bg-indigo-700 disabled:bg-indigo-400 text-white font-semibold py-3 px-6 rounded-xl shadow-lg shadow-indigo-200 dark:shadow-none transition-all flex items-center justify-center gap-2"
        >
          {loading ? <Loader2 className="animate-spin" size={20} /> : <Zap size={20} />}
          {t.generate}
        </button>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* CEFR Level Progress */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col gap-4">
          <div className="bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-400 p-2 rounded-lg w-fit">
            <Award size={24} />
          </div>
          <div className="flex justify-between items-end">
            <div>
              <p className="text-sm font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t.cefr}</p>
              <p className="text-2xl font-bold text-slate-900 dark:text-white">{profile.level}</p>
            </div>
            <div className="text-right">
              <p className="text-xs font-bold text-slate-400 dark:text-slate-500">
                {profile.level === 'C2' ? 'Mastery' : `${Math.round(progress.percentage)}% to ${progress.nextLevel}`}
              </p>
            </div>
          </div>
          <div className="w-full bg-slate-100 dark:bg-slate-800 h-2.5 rounded-full overflow-hidden">
            <div className="bg-amber-500 h-full transition-all duration-1000 ease-out" style={{ width: `${progress.percentage}%` }} />
          </div>
          {profile.level !== 'C2' ? (
            <p className="text-[10px] text-slate-400 dark:text-slate-500 flex items-center gap-1">
              <Info size={10} /> {progress.nextLevelWords} words remaining for {progress.nextLevel}
            </p>
          ) : (
            <p className="text-[10px] text-emerald-500 font-bold flex items-center gap-1"><Zap size={10} /> Maximum level reached!</p>
          )}
        </div>

        {/* Vocabulary Growth Card with Sparkline */}
        <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl shadow-sm border border-slate-100 dark:border-slate-800 flex flex-col gap-4">
          <div className="bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-400 p-2 rounded-lg w-fit">
            <TrendingUp size={24} />
          </div>
          <div>
            <p className="text-sm font-medium text-slate-500 dark:text-slate-400 uppercase tracking-wider">{t.vocab}</p>
            <p className="text-2xl font-bold text-slate-900 dark:text-white">{profile.knownWords.length} words</p>
          </div>

          {/* Simple SVG Growth Chart */}
          <div className="h-12 w-full mt-auto flex items-end gap-1">
            {growthData.length > 1 ? (
              growthData.map((p, i) => {
                const maxVal = Math.max(...growthData.map(d => d.val));
                const minVal = Math.min(...growthData.map(d => d.val));
                const height = maxVal === minVal ? 50 : ((p.val - minVal) / (maxVal - minVal) * 80 + 20);
                return (
                  <div key={i} className="flex-grow bg-blue-100 dark:bg-blue-900/20 rounded-t-sm group relative" style={{ height: `${height}%` }}>
                    <div className="opacity-0 group-hover:opacity-100 absolute -top-8 left-1/2 -translate-x-1/2 bg-slate-800 text-white text-[10px] px-1.5 py-0.5 rounded pointer-events-none whitespace-nowrap z-20">
                      {p.val} words
                    </div>
                  </div>
                );
              })
            ) : (
              <div className="w-full h-full flex items-center justify-center text-[10px] text-slate-400">Complete lessons to see growth</div>
            )}
          </div>
        </div>

