const calculateLevelFromVocab = (count: number): CEFRLevel => {
  if (count <= 500) return 'A1';
  if (count <= 1000) return 'A2';
  if (count <= 2500) return 'B1';
  if (count <= 5000) return 'B2';
  if (count <= 10000) return 'C1';
  return 'C2';
};

