  targetLanguage: string;
}

const History: React.FC<HistoryProps> = ({ history, onReopen, targetLanguage }) => {
  const [playingIdx, setPlayingIdx] = useState<number | null>(null);
  const [downloadingIdx, setDownloadingIdx] = useState<number | null>(null);

  const formatDate = (timestamp: number) => {
    return new Intl.DateTimeFormat('en-US', {
      month: 'short',
      day: 'numeric',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    }).format(new Date(timestamp));
  };

  const handlePlayHistoryAudio = async (idx: number, item: HistoryItem) => {
    if (playingIdx !== null) return;
    setPlayingIdx(idx);
    try {
      await playFullStoryAudio(item, targetLanguage);
    } catch (err: any) {
      alert(`Audio Error: ${err.message}`);
    } finally {
      setPlayingIdx(null);
    }
  };

  const handleDownloadHistoryAudio = async (idx: number, item: HistoryItem) => {
    if (downloadingIdx !== null) return;
    setDownloadingIdx(idx);
    try {
      await downloadFullStoryAudio(item, targetLanguage);
