export type CEFRLevel = 'A1' | 'A2' | 'B1' | 'B2' | 'C1' | 'C2';
export type UILanguage = 'en' | 'pt' | 'es';
export type StorySize = 'short' | 'medium' | 'long';

export interface Sentence {
  id: number;
  original: string;
  translation: string;
  phonetic: string; // New field for IPA or phonetic notation
  new_element: string;
  explanation: string;
}

export interface StoryResponse {
  story_title: string;
  level_target: CEFRLevel;
  sentences: Sentence[];
  estimated_vocab_count: string;
  new_words_to_add: string[];
}

export interface UserProfile {
  name: string;
  targetLanguage: string;
  nativeLanguage: string;
  level: CEFRLevel;
  knownWords: string[];
  uiLanguage: UILanguage;
  darkMode: boolean;
  notificationTime: string; // "HH:mm"
  notificationsEnabled: boolean;
  storySize: StorySize;
}

export interface HistoryItem extends StoryResponse {
  timestamp: number;
  completed: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CEFRLevel, StoryResponse, StorySize } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateStory = async (
  targetLanguage: string,
  nativeLanguage: string,
  level: CEFRLevel,
  knownWords: string[],
  storySize: StorySize
): Promise<StoryResponse> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const sizeMap = {
    short: "5 to 10",
    medium: "10 to 15",
    long: "15 to 25"
  };

  const sentenceCount = sizeMap[storySize] || "5 to 10";

  const prompt = `
    Act as a Natural Language Acquisition Specialist and Polyglot. 
    Generate study content following the Natural Method (i+1) strictly.

    Target Language: ${targetLanguage}
    Native Language (for translations): ${nativeLanguage}
    CEFR Level: ${level}
    Known Words List: [${knownWords.slice(0, 500).join(", ")}]

    RULES:
    1. i+1 METHOD: Create a coherent story where almost all words are known, EXCEPT for exactly one new element (word or structure) introduced per sentence.
    2. LENGTH: The story MUST contain between ${sentenceCount} sentences.
    3. CONTEXT: Ensure the story is coherent and natural.
    4. TARGET: Strictly ${level} difficulty.
    5. MANDATORY PHONETICS: You MUST provide the International Phonetic Alphabet (IPA) transcription for the 'new_element' in the context of the sentence. 
       This field 'phonetic' MUST NOT be empty. Use standard IPA symbols.
    6. LANGUAGE: All explanations should be in ${nativeLanguage}.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          story_title: { type: Type.STRING },
          level_target: { type: Type.STRING },
          sentences: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                original: { type: Type.STRING },
                translation: { type: Type.STRING },
                phonetic: { type: Type.STRING, description: "MANDATORY: Full IPA transcription of the new_element" },
                new_element: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "original", "translation", "phonetic", "new_element", "explanation"]
            }
          },
          estimated_vocab_count: { type: Type.STRING },
          new_words_to_add: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["story_title", "level_target", "sentences", "estimated_vocab_count", "new_words_to_add"]
      }
    }
  });

  return JSON.parse(response.text);
};

