  ancientGreekDialect?: AncientGreekDialect;
}

export interface HistoryItem extends StoryResponse {
  timestamp: number;
  completed: boolean;
}

import { GoogleGenAI, Type } from "@google/genai";
import { CEFRLevel, StoryResponse, StorySize, AncientGreekDialect } from "../types";

const API_KEY = process.env.API_KEY || "";

export const generateStory = async (
  targetLanguage: string,
  nativeLanguage: string,
  level: CEFRLevel,
  knownWords: string[],
  storySize: StorySize,
  ancientGreekDialect?: AncientGreekDialect
): Promise<StoryResponse> => {
  const ai = new GoogleGenAI({ apiKey: API_KEY });

  const sizeMap = {
    short: "5 to 10",
    medium: "10 to 15",
    long: "15 to 25"
  };

  const sentenceCount = sizeMap[storySize] || "5 to 10";

  // Customizing language string if Ancient Greek is selected
  let langDisplay = targetLanguage;
  if (targetLanguage === 'Ancient Greek' && ancientGreekDialect) {
    langDisplay = `Ancient Greek (${ancientGreekDialect === 'attic' ? 'Attic' : 'Koine'} dialect)`;
  }

  const prompt = `
    Act as a Natural Language Acquisition Specialist and Polyglot. 
    Generate study content following the Natural Method (i+1) strictly.

    Target Language: ${langDisplay}
    Native Language (for translations): ${nativeLanguage}
    User CEFR Level: ${level}
    Current Vocabulary Count: ${knownWords.length} words.

    CRITICAL - KNOWN VOCABULARY CONTEXT:
    The user already knows the following ${knownWords.length} words. DO NOT treat these as "new elements":
    [${knownWords.join(", ")}]

    RULES:
    1. i+1 METHOD: Create a coherent story where 95-98% of words are from the "Known Vocabulary" list above.
    2. NEW ELEMENT: Introduce EXACTLY ONE new element (word, idiom, or grammatical structure) per sentence that is NOT in the list above.
    3. LENGTH: The story MUST contain between ${sentenceCount} sentences.
    4. CONTEXT: Ensure the story is coherent and natural for the ${langDisplay} context.
    5. MANDATORY PHONETICS: Provide the IPA transcription for the 'new_element'. For Greek/Latin, ensure macrons or accents are reflected.
    6. LANGUAGE: All explanations should be in ${nativeLanguage}.
  `;

  const response = await ai.models.generateContent({
    model: "gemini-3-flash-preview",
    contents: prompt,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          story_title: { type: Type.STRING },
          level_target: { type: Type.STRING },
          sentences: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.NUMBER },
                original: { type: Type.STRING },
                translation: { type: Type.STRING },
                phonetic: { type: Type.STRING, description: "MANDATORY: IPA transcription" },
                new_element: { type: Type.STRING },
                explanation: { type: Type.STRING }
              },
              required: ["id", "original", "translation", "phonetic", "new_element", "explanation"]
            }
          },
          estimated_vocab_count: { type: Type.STRING },
          new_words_to_add: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        },
        required: ["story_title", "level_target", "sentences", "estimated_vocab_count", "new_words_to_add"]
      }
    }
  });

  return JSON.parse(response.text);
};

