export type StorySize = 'short' | 'medium' | 'long';
export type AncientGreekDialect = 'attic' | 'koine';
export type AncientGreekFocus = 'general' | 'philosophical';

export interface Sentence {
  id: number;
  original: string;
  translation: string;
  phonetic: string; 
  new_element: string;
  explanation: string;
}

export interface StoryResponse {
  story_title: string;
  level_target: CEFRLevel;
  sentences: Sentence[];
  estimated_vocab_count: string;
  new_words_to_add: string[];
}

